  'Tell me in your own words, by typing or with the mic. I can add expenses, attendance, tasks, reports and more, and answer questions about your sites. I always ask before saving anything.': 'اپنے الفاظ میں بتائیں، لکھ کر یا مائیک سے۔ میں خرچ، حاضری، کام، رپورٹیں اور بہت کچھ شامل کر سکتا ہوں، اور آپ کی سائٹس کے بارے میں سوالوں کے جواب دے سکتا ہوں۔ کچھ بھی محفوظ کرنے سے پہلے میں ہمیشہ پوچھتا ہوں۔',
  'That took too many steps. Try asking for one thing at a time.': 'اس میں بہت زیادہ مراحل لگ گئے۔ ایک وقت میں ایک چیز پوچھ کر دیکھیں۔',
  'The answer was cut short. Please ask again in fewer words.': 'جواب ادھورا رہ گیا۔ براہ کرم کم الفاظ میں دوبارہ پوچھیں۔',
  'The assistant can\'t help with that one. Try asking another way.': 'اسسٹنٹ اس میں مدد نہیں کر سکتا۔ کسی اور طرح پوچھ کر دیکھیں۔',
  'The assistant thinks on FieldOS\'s server, so it needs your FieldOS account and internet. Your site data stays on this phone; only what you ask, and what is needed to answer it, is sent.': 'اسسٹنٹ FieldOS کے سرور پر سوچتا ہے، اس لیے اسے آپ کا FieldOS اکاؤنٹ اور انٹرنیٹ چاہیے۔ آپ کی سائٹ کا ڈیٹا اسی فون پر رہتا ہے؛ صرف آپ کا سوال اور جواب کے لیے ضروری معلومات بھیجی جاتی ہیں۔',
  'Today\'s report for {site}: {text}': '{site} کی آج کی رپورٹ: {text}',
