  'Sign in to Team & sync once to use the assistant.': 'اسسٹنٹ استعمال کرنے کے لیے ایک بار Team & sync میں سائن ان کریں۔',
  'Sign in to FieldOS again to use the assistant.': 'اسسٹنٹ استعمال کرنے کے لیے FieldOS میں دوبارہ سائن ان کریں۔',
  'The assistant comes with the FieldOS plan. Start or renew it in My subscription.': 'اسسٹنٹ FieldOS پلان کے ساتھ آتا ہے۔ اسے میری سبسکرپشن میں شروع یا تجدید کریں۔',
  'You\'ve used this month\'s assistant allowance. It starts again on the 1st. Everything else in FieldOS works as usual.': 'آپ نے اس مہینے کی اسسٹنٹ حد استعمال کر لی۔ یہ 1 تاریخ کو دوبارہ شروع ہوگی۔ FieldOS میں باقی سب کچھ معمول کے مطابق چلتا ہے۔',
  'This month\'s voice allowance is used up. Please type, or use the phone\'s own voice typing.': 'اس مہینے کی آواز کی حد ختم ہو گئی۔ براہ کرم لکھیں، یا فون کی اپنی وائس ٹائپنگ استعمال کریں۔',
  'Just ask FieldOS': 'بس FieldOS سے پوچھیں',
  'Not sure where something is? Tap Ask FieldOS at the top and type or speak, like "add 5000 for cement". It does the work and asks you to tap Save first.': 'پتا نہیں کوئی چیز کہاں ہے؟ اوپر FieldOS سے پوچھیں پر ٹیپ کریں اور لکھیں یا بولیں، جیسے "سیمنٹ کے لیے 5000 شامل کرو"۔ یہ کام کر دیتا ہے اور پہلے آپ سے "محفوظ کریں" پر ٹیپ کرواتا ہے۔',
  '{n}% of this month\'s assistant use is left': 'اس مہینے کے اسسٹنٹ استعمال کا {n}% باقی ہے',
  'You\'ve used the assistant a lot today. It will be ready again tomorrow.': 'آپ نے آج اسسٹنٹ بہت استعمال کیا۔ یہ کل دوبارہ تیار ہوگا۔',
  'No internet. The assistant needs internet; everything else in FieldOS works offline.': 'انٹرنیٹ نہیں۔ اسسٹنٹ کو انٹرنیٹ چاہیے؛ FieldOS میں باقی سب کچھ آف لائن چلتا ہے۔',
  'The assistant could not answer just now. Please try again in a minute.': 'اسسٹنٹ ابھی جواب نہیں دے سکا۔ براہ کرم ایک منٹ میں دوبارہ کوشش کریں۔',
  'The assistant is not switched on yet. Please try again later.': 'اسسٹنٹ ابھی آن نہیں ہوا۔ براہ کرم بعد میں دوبارہ کوشش کریں۔',
