  'Namaste! I am Mitra, your site buddy': 'السلام علیکم! میں Mitra ہوں، آپ کا سائٹ ساتھی',
  'Let me show you one day on a real site: Mr. Reddy\'s G+1 house. It takes two minutes and does not touch your own data.': 'آئیں آپ کو ایک اصلی سائٹ کا ایک دن دکھاؤں: ریڈی صاحب کا G+1 گھر۔ اس میں دو منٹ لگتے ہیں اور آپ کے اپنے ڈیٹا کو نہیں چھیڑتا۔',
  'All your sites in one list': 'آپ کی تمام سائٹس ایک لسٹ میں',
  'Each site shows its stage and anything running late. Tap a site to open its tasks, labour, money and reports.': 'ہر سائٹ اپنا مرحلہ اور جو کچھ لیٹ ہو رہا ہے دکھاتی ہے۔ کسی سائٹ کے کام، مزدور، پیسہ اور رپورٹیں کھولنے کے لیے اس پر ٹیپ کریں۔',
  'Plan the day': 'دن کی منصوبہ بندی',
  'Tasks show how far each job has got and what is slipping. The plinth beam is late, so it is marked in red before anyone has to ask.': 'کام دکھاتے ہیں کہ ہر کام کتنا ہوا اور کیا پیچھے رہ رہا ہے۔ پلنتھ بیم لیٹ ہے، اس لیے کسی کے پوچھنے سے پہلے ہی سرخ نشان لگ جاتا ہے۔',
  'Attendance in two taps': 'دو ٹیپ میں حاضری',
  'Punch workers in as they arrive, or mark the whole gang at once. Hours, half days and overtime are worked out for you.': 'ورکرز کے آتے ہی انہیں پنچ اِن کریں، یا پوری ٹولی ایک ساتھ لگائیں۔ گھنٹے، آدھے دن اور اوور ٹائم آپ کے لیے نکال دیے جاتے ہیں۔',
  'Cement arrives': 'سیمنٹ آ گیا',
  'Raise a purchase order, then receive what actually came. A part delivery keeps the order open, and stock updates itself.': 'خریداری آرڈر بنائیں، پھر جو اصل میں آیا وہ وصول کریں۔ ادھوری ڈیلیوری پر آرڈر کھلا رہتا ہے، اور اسٹاک خود اپ ڈیٹ ہوتا ہے۔',
  'Every rupee on site': 'سائٹ کا ہر درہم',
  'Money received, money spent and the balance, by category. Client bills and GST invoices are made here too.': 'زمرے کے حساب سے موصول رقم، خرچ اور بیلنس۔ کلائنٹ کے بل اور VAT انوائسز بھی یہیں بنتی ہیں۔',
  'Problems do not get lost': 'مسئلے گم نہیں ہوتے',
  'Cement ran short for the column casting. Raise it once and it stays open, with photos, until someone marks it fixed.': 'کالم کی ڈھلائی کے لیے سیمنٹ کم پڑ گیا۔ ایک بار اٹھائیں اور یہ تصاویر کے ساتھ تب تک کھلا رہتا ہے جب تک کوئی اسے ٹھیک شدہ نہ لگائے۔',
  'Speak the daily report': 'روزانہ رپورٹ بولیں',
  'Tap Speak report and just talk, in Telugu, Hindi or English. FieldOS writes the report, adds the day\'s numbers and shares a PDF on WhatsApp.': 'رپورٹ بولیں پر ٹیپ کریں اور بس بولیں، تیلگو، ہندی یا انگریزی میں۔ FieldOS رپورٹ لکھتا ہے، دن کے اعداد شامل کرتا ہے اور WhatsApp پر PDF شیئر کرتا ہے۔',
  'Wages without a calculator': 'کیلکولیٹر کے بغیر تنخواہ',
  'The wage sheet adds up each worker\'s days, advances and what is still due, ready to pay or send to the contractor.': 'تنخواہ شیٹ ہر ورکر کے دن، ایڈوانس اور باقی رقم جوڑ دیتی ہے، ادائیگی یا لیبر سپلائی کمپنی کو بھیجنے کے لیے تیار۔',
  'Every site at a glance': 'ہر سائٹ ایک نظر میں',
  'Owners see spending against budget, progress and open problems across all sites, without a single phone call.': 'مالکان تمام سائٹس پر بجٹ کے مقابلے خرچ، پیش رفت اور کھلے مسائل دیکھتے ہیں، ایک بھی فون کال کے بغیر۔',
