  'No internet connection. Your work is saved on this phone; try again when you are online.': 'انٹرنیٹ کنکشن نہیں۔ آپ کا کام اس فون پر محفوظ ہے؛ آن لائن ہونے پر دوبارہ کوشش کریں۔',
  'Not {name}? Log out': '{name} نہیں ہیں؟ لاگ آؤٹ کریں',
  'Only for people the FieldOS team gave a code to, such as app reviewers.': 'صرف ان لوگوں کے لیے جنہیں FieldOS ٹیم نے کوڈ دیا ہے، جیسے ایپ ریویو کرنے والے۔',
  'Only the company owner can change roles.': 'صرف کمپنی کا مالک رول بدل سکتا ہے۔',
