  'Something went wrong. Please try again, or send a bug report from the menu.': 'کچھ غلط ہو گیا۔ دوبارہ کوشش کریں، یا مینو سے بگ رپورٹ بھیجیں۔',
  'Start {length} free trial': '{length} کا مفت ٹرائل شروع کریں',
  'Still waiting for the payment. It can take a few minutes after you approve it.': 'ابھی ادائیگی کا انتظار ہے۔ منظوری کے بعد چند منٹ لگ سکتے ہیں۔',
