  'Terms': 'شرائط',
  'That code is not right, or it is too old. Check it, or send a new code.': 'یہ کوڈ درست نہیں، یا بہت پرانا ہے۔ اسے چیک کریں، یا نیا کوڈ منگوائیں۔',
  'That email address cannot be used. Check it, or try another.': 'یہ ای میل ایڈریس استعمال نہیں ہو سکتا۔ اسے چیک کریں، یا کوئی اور آزمائیں۔',
  'That email already has a FieldOS cloud account. Sign in with its password.': 'اس ای میل کا پہلے سے FieldOS کلاؤڈ اکاؤنٹ ہے۔ اس کے پاس ورڈ سے سائن ان کریں۔',
  'That email and password do not match. Check them and try again.': 'ای میل اور پاس ورڈ میل نہیں کھاتے۔ انہیں چیک کر کے دوبارہ کوشش کریں۔',
  'That is already your password. Choose a different one, or sign in with it.': 'یہ پہلے ہی آپ کا پاس ورڈ ہے۔ کوئی دوسرا چنیں، یا اسی سے سائن ان کریں۔',
  'That join code is not right. Check it with the person who shared it: it is 10 letters and numbers.': 'یہ شمولیت کوڈ درست نہیں۔ جس نے شیئر کیا اس سے چیک کریں: یہ 10 حروف اور نمبر ہوتا ہے۔',
  'That took too long. Check your connection and try again.': 'بہت وقت لگ گیا۔ اپنا کنکشن چیک کر کے دوبارہ کوشش کریں۔',
  'The FieldOS cloud is not answering right now. Your work is saved on this phone; try again in a few minutes.': 'FieldOS کلاؤڈ ابھی جواب نہیں دے رہا۔ آپ کا کام اس فون پر محفوظ ہے؛ چند منٹ بعد دوبارہ کوشش کریں۔',
  'The FieldOS team gave you this access, so there is nothing to pay or cancel. When it ends, FieldOS asks you to choose a plan, and your records stay on this phone.': 'یہ رسائی FieldOS ٹیم نے دی ہے، اس لیے کچھ ادا یا منسوخ نہیں کرنا۔ ختم ہونے پر FieldOS آپ سے پلان چننے کو کہے گا، اور آپ کا ریکارڈ اس فون پر رہے گا۔',
  'The company owner cannot be removed from the team.': 'کمپنی کے مالک کو ٹیم سے نہیں نکالا جا سکتا۔',
  'The purchase did not finish. Please try again.': 'خریداری مکمل نہیں ہوئی۔ دوبارہ کوشش کریں۔',
  'The subscription is not on sale yet. Please try again later.': 'سبسکرپشن ابھی فروخت کے لیے دستیاب نہیں۔ بعد میں دوبارہ کوشش کریں۔',
  'This company is already on the cloud under another account. Ask its owner for a join code.': 'یہ کمپنی پہلے سے کسی اور اکاؤنٹ کے تحت کلاؤڈ پر ہے۔ اس کے مالک سے شمولیت کوڈ مانگیں۔',
  'This is a one-time download of about 30 MB. After that, {language} reports translate to English on this phone, with no internet and no cost.': 'یہ تقریباً 30 MB کا ایک بار کا ڈاؤن لوڈ ہے۔ اس کے بعد {language} رپورٹیں اسی فون پر انگریزی میں ترجمہ ہوں گی، بغیر انٹرنیٹ اور بغیر خرچ کے۔',
  'To cancel, open {path}. You keep FieldOS Pro until the end of the period you have paid for, and your records stay on this phone.': 'منسوخ کرنے کے لیے {path} کھولیں۔ ادا شدہ مدت کے آخر تک FieldOS Pro آپ کے پاس رہے گا، اور آپ کا ریکارڈ اس فون پر رہے گا۔',
