  'Their chat messages are hidden on this phone. They stay in the company, and their site records are not hidden.': 'ان کے چیٹ پیغامات اس فون پر چھپے ہوئے ہیں۔ وہ کمپنی میں رہیں گے، اور ان کا سائٹ ریکارڈ نہیں چھپا۔',
