  'One project for each site. Its daily reports, labour, materials, money and photos stay together.': 'ہر سائٹ کے لیے ایک پروجیکٹ۔ اس کی روزانہ رپورٹیں، مزدور، مٹیریل، پیسہ اور تصاویر ایک ساتھ رہتی ہیں۔',
  'Payment problem: update your payment method in the store': 'ادائیگی میں مسئلہ: اسٹور میں اپنا ادائیگی کا طریقہ اپ ڈیٹ کریں',
  'Payment problem: update your payment method in the store before {date}': 'ادائیگی میں مسئلہ: {date} سے پہلے اسٹور میں اپنا ادائیگی کا طریقہ اپ ڈیٹ کریں',
