  'Synced. {n} changes sent, latest data received.': 'سنک ہو گیا۔ {n} تبدیلیاں بھیجیں، تازہ ڈیٹا مل گیا۔',
  'Tap the mic and speak': 'مائیک ٹیپ کریں اور بولیں',
  'Tap to start recording': 'ریکارڈنگ شروع کرنے کے لیے ٹیپ کریں',
  'That code is not valid or has ended. Check it and try again, or ask whoever gave it to you.': 'یہ کوڈ درست نہیں یا ختم ہو چکا ہے۔ چیک کر کے دوبارہ کوشش کریں، یا جس نے دیا اس سے پوچھیں۔',
  'That plan is no longer on sale. Please pick again.': 'یہ پلان اب فروخت میں نہیں۔ دوبارہ چنیں۔',
  'The FieldOS plans are not on sale in {store} yet. Please try again later, or send a bug report from the menu.': 'FieldOS پلان ابھی {store} میں فروخت کے لیے نہیں ہیں۔ بعد میں دوبارہ کوشش کریں، یا مینو سے بگ رپورٹ بھیجیں۔',
  'The owner or a project manager decides these. You can see what is waiting.': 'ان کا فیصلہ مالک یا پروجیکٹ مینیجر کرتا ہے۔ آپ دیکھ سکتے ہیں کیا زیر التوا ہے۔',
  'The phone stopped listening. Tap Try again, or type the report.': 'فون نے سننا بند کر دیا۔ دوبارہ کوشش پر ٹیپ کریں، یا رپورٹ لکھیں۔',
  'There is no internet, and the offline speech pack for {language} is not on this phone yet. Connect once, then download it: Google app › Settings › Voice › Offline speech recognition › {englishName}. After that, voice reports work anywhere on site.': 'انٹرنیٹ نہیں ہے، اور {language} کا آف لائن اسپیچ پیک ابھی اس فون پر نہیں۔ ایک بار کنیکٹ کریں، پھر اسے ڈاؤن لوڈ کریں: Google app › Settings › Voice › Offline speech recognition › {englishName}۔ اس کے بعد وائس رپورٹیں سائٹ پر کہیں بھی چلیں گی۔',
  'This iPhone needs internet to recognise {language} speech. Connect and try again, or type the report.': 'اس iPhone کو {language} بولی پہچاننے کے لیے انٹرنیٹ چاہیے۔ کنیکٹ کر کے دوبارہ کوشش کریں، یا رپورٹ لکھیں۔',
  'This needs internet for {language}': '{language} کے لیے انٹرنیٹ چاہیے',
  'This permanently deletes {email} from FieldOS cloud.': 'یہ {email} کو FieldOS کلاؤڈ سے ہمیشہ کے لیے حذف کر دے گا۔',
  'This phone can\'t do {language} yet': 'یہ فون ابھی {language} نہیں سمجھ سکتا',
  'This phone can\'t turn {language} speech into text itself, so FieldOS will record you and send the recording to Sarvam when you stop. This needs internet.': 'یہ فون خود {language} بولی کو تحریر میں نہیں بدل سکتا، اس لیے FieldOS آپ کی ریکارڈنگ کرے گا اور روکنے پر اسے Sarvam کو بھیجے گا۔ اس کے لیے انٹرنیٹ چاہیے۔',
  'This phone has no speech recognition': 'اس فون میں بولی پہچاننے کی سہولت نہیں',
  'This phone is not allowed to make purchases. Check the payment settings or parental controls in {store}.': 'اس فون کو خریداری کی اجازت نہیں۔ {store} میں ادائیگی کی سیٹنگز یا پیرنٹل کنٹرول چیک کریں۔',
  'This plan is not on sale in your country right now.': 'یہ پلان ابھی آپ کے ملک میں فروخت کے لیے نہیں۔',
  'This {store} account already pays for FieldOS for someone else. Write to us and we will sort it out.': 'یہ {store} اکاؤنٹ پہلے ہی کسی اور کے لیے FieldOS کی ادائیگی کرتا ہے۔ ہمیں لکھیں، ہم اسے حل کر دیں گے۔',
  'Turning your recording into text…': 'آپ کی ریکارڈنگ کو تحریر میں بدلا جا رہا ہے…',
  'Turning your recording into text… {n} of {total}': 'آپ کی ریکارڈنگ کو تحریر میں بدلا جا رہا ہے… {total} میں سے {n}',
  'Type the code from the email: it is 6 digits.': 'ای میل والا کوڈ لکھیں: یہ 6 ہندسوں کا ہے۔',
