  'Type the code we emailed to {email}. It can take a minute to arrive; look in spam too.': '{email} پر ای میل کیا گیا کوڈ لکھیں۔ آنے میں ایک منٹ لگ سکتا ہے؛ اسپام میں بھی دیکھیں۔',
  'Type your email above first, then tap "Forgot password?" again.': 'پہلے اوپر اپنی ای میل لکھیں، پھر دوبارہ "پاس ورڈ بھول گئے؟" پر ٹیپ کریں۔',
  'We sent a code to {email}. Type it below to finish creating your account.': 'ہم نے {email} پر کوڈ بھیجا ہے۔ اکاؤنٹ بنانا مکمل کرنے کے لیے اسے نیچے لکھیں۔',
  'Work measured this bill': 'اس بل میں ناپا گیا کام',
