  'Complaints': 'شکایات',
  'For building work, GST follows the state where the site is. Inside your state it splits into CGST and SGST': 'تعمیراتی کام کے لیے VAT اس ریاست کے مطابق لگتا ہے جہاں سائٹ ہے۔ آپ کی اپنی ریاست کے اندر یہ CGST اور SGST میں تقسیم ہوتا ہے',
  'Google Play or the App Store take the payment. RevenueCat in the USA gets the purchase record so the app can check your plan. We never see card or UPI details.': 'ادائیگی Google Play یا App Store لیتے ہیں۔ امریکہ میں RevenueCat کو خریداری کا ریکارڈ ملتا ہے تاکہ ایپ آپ کا پلان چیک کر سکے۔ ہم کبھی کارڈ یا فوری ٹرانسفر کی تفصیلات نہیں دیکھتے۔',
  'I agree': 'میں متفق ہوں',
  'In Team & sync. This also withdraws your consent.': 'Team & sync میں۔ اس سے آپ کی رضامندی بھی واپس ہو جاتی ہے۔',
  'Let Ask FieldOS send questions to AI': 'Ask FieldOS کو سوالات AI کو بھیجنے دیں',
  'Location and selfies': 'لوکیشن اور سیلفیاں',
  'Name someone to act for me': 'میری طرف سے کام کرنے کے لیے کسی کو نامزد کریں',
  'Only what you send us, and crash details if that setting is on, so that we can fix problems.': 'صرف وہ جو آپ ہمیں بھیجیں، اور اگر سیٹنگ آن ہو تو کریش کی تفصیلات، تاکہ ہم مسائل ٹھیک کر سکیں۔',
  'Only when you use it: what you ask, and the site details needed to answer, go to Anthropic in the USA (or Sarvam AI in India as a backup) to work out the reply. They do not use it to train their models.': 'صرف جب آپ اسے استعمال کریں: آپ کا سوال، اور جواب کے لیے ضروری سائٹ کی تفصیلات، جواب تیار کرنے کے لیے امریکہ میں Anthropic (یا بیک اپ کے طور پر بھارت میں Sarvam AI) کو جاتی ہیں۔ وہ اسے اپنے ماڈلز کی تربیت کے لیے استعمال نہیں کرتے۔',
  'Paying for FieldOS': 'FieldOS کی ادائیگی',
  'Projects, reports, photos, attendance, wages and other records your company keeps. They stay on this phone, and in our cloud in Mumbai, India when Team & sync is on, so that your team can see them.': 'پروجیکٹس، رپورٹیں، تصاویر، حاضری، اجرت اور دوسرے ریکارڈ جو آپ کی کمپنی رکھتی ہے۔ یہ اس فون پر رہتے ہیں، اور جب Team & sync آن ہو تو ممبئی، بھارت میں ہمارے کلاؤڈ میں، تاکہ آپ کی ٹیم انہیں دیکھ سکے۔',
  'Read the full privacy policy': 'مکمل پرائیویسی پالیسی پڑھیں',
  'Site records': 'سائٹ کے ریکارڈ',
  'The AI assistant': 'AI معاون',
  'To answer, FieldOS sends what you type or say, and the site details needed for the answer (such as project names, workers, tasks and amounts), to Anthropic in the USA. If Anthropic is not available, it goes to Sarvam AI in India instead. They work out the reply and do not use it to train their models. FieldOS keeps only how much you used the assistant.': 'جواب دینے کے لیے FieldOS آپ کا لکھا یا بولا ہوا، اور جواب کے لیے ضروری سائٹ کی تفصیلات (جیسے پروجیکٹ کے نام، مزدور، کام اور رقمیں)، امریکہ میں Anthropic کو بھیجتا ہے۔ اگر Anthropic دستیاب نہ ہو تو یہ بھارت میں Sarvam AI کو جاتا ہے۔ وہ جواب تیار کرتے ہیں اور اسے اپنے ماڈلز کی تربیت کے لیے استعمال نہیں کرتے۔ FieldOS صرف یہ رکھتا ہے کہ آپ نے معاون کو کتنا استعمال کیا۔',
  'What FieldOS collects and why': 'FieldOS کیا جمع کرتا ہے اور کیوں',
  'What is collected and why, your rights, and the AI assistant permission': 'کیا جمع ہوتا ہے اور کیوں، آپ کے حقوق، اور AI معاون کی اجازت',
  'Write from the email address on your account. We reply within 30 days. If you are not satisfied, you can complain to the Data Protection Board of India.': 'اپنے اکاؤنٹ والے ای میل پتے سے لکھیں۔ ہم 30 دن میں جواب دیتے ہیں۔ اگر آپ مطمئن نہ ہوں تو بھارت کے ڈیٹا پروٹیکشن بورڈ سے شکایت کر سکتے ہیں۔',
  'Write to our Grievance Officer at info@mldynamic.com. We reply within 30 days. You can also complain to the Data Protection Board of India.': 'ہمارے شکایت افسر کو info@mldynamic.com پر لکھیں۔ ہم 30 دن میں جواب دیتے ہیں۔ آپ بھارت کے ڈیٹا پروٹیکشن بورڈ سے بھی شکایت کر سکتے ہیں۔',
  'Write to {email} with "{subject}" as the subject.': '{email} پر "{subject}" کو موضوع رکھ کر لکھیں۔',
  'You can stop the AI assistant, turn off crash details, export your records or delete your cloud account at any time. Stopping does not change what was done before.': 'آپ کسی بھی وقت AI معاون بند کر سکتے ہیں، کریش کی تفصیلات بند کر سکتے ہیں، اپنے ریکارڈ ایکسپورٹ کر سکتے ہیں یا اپنا کلاؤڈ اکاؤنٹ حذف کر سکتے ہیں۔ بند کرنے سے پہلے کیا گیا کام نہیں بدلتا۔',
  'You can stop this at any time in Settings, Your privacy.': 'آپ اسے کسی بھی وقت سیٹنگز، آپ کی پرائیویسی میں بند کر سکتے ہیں۔',
  'Your account': 'آپ کا اکاؤنٹ',
  'Your choices': 'آپ کے اختیارات',
  'Your location, and a selfie, only when you check in or out, punch a worker in, set a site location or take a site photo, to show the work was done at the site. Never in the background.': 'آپ کی لوکیشن، اور سیلفی، صرف جب آپ حاضری لگائیں یا چھٹی درج کریں، کسی مزدور کا پنچ لگائیں، سائٹ کی لوکیشن طے کریں یا سائٹ کی تصویر لیں، یہ دکھانے کے لیے کہ کام سائٹ پر ہوا۔ کبھی پس منظر میں نہیں۔',
  'Your name, email address and the company you join, so that you can sign in and work with your team.': 'آپ کا نام، ای میل پتہ اور وہ کمپنی جس میں آپ شامل ہوں، تاکہ آپ سائن ان کر کے اپنی ٹیم کے ساتھ کام کر سکیں۔',
  'Your privacy': 'آپ کی پرائیویسی',
  'Your rights': 'آپ کے حقوق',
  'A Zoho Books file, with tax split out': 'Zoho Books فائل، ٹیکس الگ کر کے',
  'Add your tax number and address': 'اپنا ٹیکس نمبر اور پتہ شامل کریں',
  'Client\'s {label} (optional)': 'کلائنٹ کا {label} (اختیاری)',
  'Kept back by the client for the tax office': 'ٹیکس آفس کے لیے کلائنٹ کی روکی ہوئی رقم',
  '{tax} rate': '{tax} کی شرح',
  'Job records': 'کام کے ریکارڈ',
  'Projects, logs, photos, time cards, pay and other records your company keeps. They stay on this phone, and in our cloud when Team & sync is on, so that your team can see them. Our cloud is in India today.': 'پروجیکٹس، لاگ، تصاویر، ٹائم کارڈ، تنخواہ اور دوسرے ریکارڈ جو آپ کی کمپنی رکھتی ہے۔ یہ اس فون پر رہتے ہیں، اور جب Team & sync آن ہو تو ہمارے کلاؤڈ میں، تاکہ آپ کی ٹیم انہیں دیکھ سکے۔ ہمارا کلاؤڈ ابھی بھارت میں ہے۔',
  'Location and photo check-in': 'لوکیشن اور تصویر سے حاضری',
  'Your location, and a photo, only when you clock in or out, clock a worker in, set a job location or take a job photo, to show the work was done on the job. Never in the background. FieldOS does not use face recognition and keeps no face scan.': 'آپ کی لوکیشن، اور ایک تصویر، صرف جب آپ آمد یا روانگی درج کریں، کسی مزدور کی آمد درج کریں، کام کی لوکیشن طے کریں یا کام کی تصویر لیں، یہ دکھانے کے لیے کہ کام موقع پر ہوا۔ کبھی پس منظر میں نہیں۔ FieldOS چہرے کی شناخت استعمال نہیں کرتا اور چہرے کا کوئی اسکین نہیں رکھتا۔',
  'Only when you use it: what you ask, and the job details needed to answer, go to Anthropic in the USA (or Sarvam AI in India as a backup) to work out the reply. Photos and locations are never sent. They do not use it to train their models.': 'صرف جب آپ اسے استعمال کریں: آپ کا سوال، اور جواب کے لیے ضروری کام کی تفصیلات، جواب تیار کرنے کے لیے امریکہ میں Anthropic (یا بیک اپ کے طور پر بھارت میں Sarvam AI) کو جاتی ہیں۔ تصاویر اور لوکیشن کبھی نہیں بھیجی جاتیں۔ وہ اسے اپنے ماڈلز کی تربیت کے لیے استعمال نہیں کرتے۔',
  'Google Play or the App Store take the payment. RevenueCat in the USA gets the purchase record so the app can check your plan. We never see card details.': 'ادائیگی Google Play یا App Store لیتے ہیں۔ امریکہ میں RevenueCat کو خریداری کا ریکارڈ ملتا ہے تاکہ ایپ آپ کا پلان چیک کر سکے۔ ہم کبھی کارڈ کی تفصیلات نہیں دیکھتے۔',
  'You can stop the AI assistant, turn off crash details, export your records or delete your cloud account at any time. We do not sell or share your personal information, and we do not use it for targeted ads.': 'آپ کسی بھی وقت AI معاون بند کر سکتے ہیں، کریش کی تفصیلات بند کر سکتے ہیں، اپنے ریکارڈ ایکسپورٹ کر سکتے ہیں یا اپنا کلاؤڈ اکاؤنٹ حذف کر سکتے ہیں۔ ہم آپ کی ذاتی معلومات نہ بیچتے ہیں نہ شیئر کرتے ہیں، اور نہ ہی اسے ٹارگٹڈ اشتہارات کے لیے استعمال کرتے ہیں۔',
  'Your privacy rights': 'آپ کے پرائیویسی کے حقوق',
  'Ask us what we hold about you, to correct it, delete it or get a copy, or let someone act for you. Write to info@mldynamic.com. We reply within 45 days.': 'ہم سے پوچھیں کہ ہمارے پاس آپ کے بارے میں کیا ہے، اسے درست یا حذف کروائیں یا اس کی کاپی لیں، یا کسی کو اپنی طرف سے کام کرنے دیں۔ info@mldynamic.com پر لکھیں۔ ہم 45 دن میں جواب دیتے ہیں۔',
  'Appeals': 'اپیلیں',
  'If we turn down a request, write to info@mldynamic.com with the word "Appeal" and we will look at it again. If you are still not satisfied, you can contact your state attorney general.': 'اگر ہم کوئی درخواست رد کریں تو info@mldynamic.com پر "Appeal" لکھ کر بھیجیں اور ہم اسے دوبارہ دیکھیں گے۔ اگر آپ پھر بھی مطمئن نہ ہوں تو اپنی ریاست کے اٹارنی جنرل سے رابطہ کر سکتے ہیں۔',
  'Appeal a privacy decision': 'پرائیویسی کے فیصلے کے خلاف اپیل کریں',
  'Write from the email address on your account. We reply within 45 days. If you are not satisfied, you can appeal, and then contact the authority for privacy where you live.': 'اپنے اکاؤنٹ والے ای میل پتے سے لکھیں۔ ہم 45 دن میں جواب دیتے ہیں۔ اگر آپ مطمئن نہ ہوں تو اپیل کر سکتے ہیں، اور پھر اپنے علاقے کی پرائیویسی اتھارٹی سے رابطہ کر سکتے ہیں۔',
  'Bar size (#3 to #18)': 'سریے کا سائز (#3 سے #18)',
  '{lb} lb per foot': '{lb} lb فی فٹ',
  '{lb} lb for {ft} ft': '{ft} فٹ کے لیے {lb} lb',
  'Standard rebar weights (ASTM A615). Bar #4 is 4/8 inch across.': 'سریے کے معیاری وزن (ASTM A615)۔ سریا #4 کی موٹائی 4/8 انچ ہے۔',
  'count': 'گنتی',
  'Foot': 'فٹ',
  'Hectare': 'ہیکٹر',
