  'Add your {label} in "Your details on bills" first. Without it a bill cannot charge {tax}; pick None.': 'پہلے "بلوں پر آپ کی تفصیلات" میں اپنا {label} شامل کریں۔ اس کے بغیر بل پر {tax} نہیں لگ سکتا؛ "کوئی نہیں" چنیں۔',
  'This site has only {qty} on record.': 'اس سائٹ کے ریکارڈ میں صرف {qty} ہے۔',
  'Expired permit': 'میعاد ختم پرمٹ',
  '{what} has expired. Working on site without it can break the law. Renew it first if you can.': '{what} کی میعاد ختم ہو گئی ہے۔ اس کے بغیر سائٹ پر کام کرنا قانون کی خلاف ورزی ہو سکتا ہے۔ ہو سکے تو پہلے اسے رینیو کریں۔',
  'Punch in anyway': 'پھر بھی پنچ کریں',
  'A permit or card expires soon': 'ایک پرمٹ یا کارڈ جلد ختم ہو رہا ہے',
  '{n} permits or cards expire soon': '{n} پرمٹ یا کارڈ جلد ختم ہو رہے ہیں',
  'Permits and cards': 'پرمٹ اور کارڈ',
  'A permit or card has expired': 'ایک پرمٹ یا کارڈ کی میعاد ختم ہو گئی ہے',
  '{days} days left': '{days} دن باقی',
  'Valid': 'درست',
  'No permits yet. Open a worker and add their permits and cards, with the expiry dates.': 'ابھی کوئی پرمٹ نہیں۔ کسی مزدور کو کھولیں اور میعاد کی تاریخوں کے ساتھ اس کے پرمٹ اور کارڈ شامل کریں۔',
  'Reminders come 90, 60, 30 and 7 days before each date. Renew before the date, not after.': 'ہر تاریخ سے 90، 60، 30 اور 7 دن پہلے یاد دہانی آتی ہے۔ تاریخ سے پہلے رینیو کریں، بعد میں نہیں۔',
  'Not added': 'شامل نہیں',
