  'Too many wrong PINs. The app lock is off. Log in again with your password.': 'بہت بار غلط PIN۔ ایپ لاک بند ہو گیا ہے۔ اپنے پاس ورڈ سے دوبارہ لاگ ان کریں۔',
  'Offline for over 7 days. Connect to the internet to keep making changes. You can still view everything.': '7 دن سے زیادہ آف لائن۔ تبدیلیاں جاری رکھنے کے لیے انٹرنیٹ سے جڑیں۔ آپ اب بھی سب کچھ دیکھ سکتے ہیں۔',
  'Your company plan has ended. Connect to the internet to check it. You can still view everything.': 'آپ کی کمپنی کا پلان ختم ہو گیا ہے۔ چیک کرنے کے لیے انٹرنیٹ سے جڑیں۔ آپ اب بھی سب کچھ دیکھ سکتے ہیں۔',
  'Rest day and public holidays': 'آرام کا دن اور سرکاری چھٹیاں',
  'Work on the rest day pays 1 day for up to half the normal hours and 2 days for more. Work on a public holiday pays 2 days on top of the holiday pay. A day you mark by hand keeps your mark.': 'آرام کے دن کام کرنے پر عام گھنٹوں کے آدھے تک 1 دن اور اس سے زیادہ پر 2 دن کی اجرت ملتی ہے۔ سرکاری چھٹی پر کام کرنے پر چھٹی کی اجرت کے اوپر 2 دن کی اجرت ملتی ہے۔ جو دن آپ خود نشان زد کریں وہ آپ کے نشان پر ہی رہتا ہے۔',
  'Rest day': 'آرام کا دن',
  'Friday (Kelantan, Terengganu, Kedah)': 'جمعہ (کلنتن، ترینگانو، کیداہ)',
  'Public holidays': 'سرکاری چھٹیاں',
  'Add the federal and state holidays your company gives, from the gazette for your state.': 'اپنی ریاست کے گزٹ سے وہ وفاقی اور ریاستی چھٹیاں شامل کریں جو آپ کی کمپنی دیتی ہے۔',
  'Projects, reports, photos, attendance, wages, work permits and other records your company keeps. They stay on this phone, and in our cloud in Mumbai, India when Team & sync is on, so that your team can see them. Your company decides what it records and is responsible for it.': 'پروجیکٹس، رپورٹیں، تصاویر، حاضری، اجرت، ورک پرمٹ اور دوسرے ریکارڈ جو آپ کی کمپنی رکھتی ہے۔ یہ اس فون پر رہتے ہیں، اور جب Team & sync آن ہو تو ممبئی، بھارت میں ہمارے کلاؤڈ میں، تاکہ آپ کی ٹیم انہیں دیکھ سکے۔ آپ کی کمپنی طے کرتی ہے کہ وہ کیا ریکارڈ کرے اور وہی اس کی ذمہ دار ہے۔',
  'Your location, and a selfie if your company uses selfie attendance, only when you check in or out, punch a worker in, set a site location or take a site photo, to show the work was done at the site. Never in the background. FieldOS does not use face recognition.': 'آپ کی لوکیشن، اور اگر آپ کی کمپنی سیلفی حاضری استعمال کرتی ہے تو سیلفی، صرف جب آپ حاضری لگائیں یا چھٹی درج کریں، کسی مزدور کا پنچ لگائیں، سائٹ کی لوکیشن طے کریں یا سائٹ کی تصویر لیں، یہ دکھانے کے لیے کہ کام سائٹ پر ہوا۔ کبھی پس منظر میں نہیں۔ FieldOS چہرے کی شناخت استعمال نہیں کرتا۔',
  'Data sent outside Malaysia': 'ملائیشیا سے باہر بھیجا جانے والا ڈیٹا',
  'Our cloud is in India, and the services above are in India and the USA. Each gets only what it needs, under a contract that requires it to keep the data safe.': 'ہمارا کلاؤڈ بھارت میں ہے، اور اوپر دی گئی سروسز بھارت اور امریکہ میں ہیں۔ ہر ایک کو صرف وہی ملتا ہے جس کی اسے ضرورت ہے، ایک معاہدے کے تحت جو ڈیٹا کو محفوظ رکھنا لازمی بناتا ہے۔',
  'Your rights under the PDPA': 'PDPA کے تحت آپ کے حقوق',
  'Ask us for access to your data or a copy, to correct it, or to send it to another organisation. Write to info@mldynamic.com. We reply within 21 days.': 'اپنے ڈیٹا تک رسائی یا اس کی کاپی، اسے درست کرنے، یا کسی دوسرے ادارے کو بھیجنے کے لیے ہم سے کہیں۔ info@mldynamic.com پر لکھیں۔ ہم 21 دن میں جواب دیتے ہیں۔',
  'Write to info@mldynamic.com with "Privacy" in the subject. If you are not satisfied, you can complain to the Personal Data Protection Commissioner of Malaysia.': 'info@mldynamic.com پر "Privacy" کو موضوع میں لکھ کر بھیجیں۔ اگر آپ مطمئن نہ ہوں تو ملائیشیا کے پرسنل ڈیٹا پروٹیکشن کمشنر سے شکایت کر سکتے ہیں۔',
  'Minimum wage: RM1,700 a month (Minimum Wages Order 2025). In Sabah and Sarawak, the Sabah Labour Ordinance or the Sarawak Labour Ordinance applies instead of the Employment Act 1955 for overtime, rest days and holidays: check the rules for your site.': 'کم از کم اجرت: RM1,700 ماہانہ (Minimum Wages Order 2025)۔ صباح اور سراواک میں اوور ٹائم، آرام کے دنوں اور چھٹیوں کے لیے Employment Act 1955 کی بجائے صباح لیبر آرڈیننس یا سراواک لیبر آرڈیننس لاگو ہوتا ہے: اپنی سائٹ کے قواعد چیک کریں۔',
  'below the minimum wage of {amount}/day': 'کم از کم اجرت {amount}/دن سے کم',
  'Write from the email address on your account. We reply within 21 days. If you are not satisfied, you can complain to the Personal Data Protection Commissioner of Malaysia.': 'اپنے اکاؤنٹ والے ای میل پتے سے لکھیں۔ ہم 21 دن میں جواب دیتے ہیں۔ اگر آپ مطمئن نہ ہوں تو ملائیشیا کے پرسنل ڈیٹا پروٹیکشن کمشنر سے شکایت کر سکتے ہیں۔',
  'Midday break season': 'دوپہر کے وقفے کا سیزن',
  'No outdoor work from {from} to {to} until {end}. Give shade, water and rest.': '{end} تک روزانہ {from} سے {to} تک باہر کام نہیں۔ سایہ، پانی اور آرام دیں۔',
  'Midday break': 'دوپہر کا وقفہ',
  'Outdoor work in the sun is not allowed from {from} to {to}, 15 June to 15 September. Punch in only for indoor or shaded work, or work that is exempt, such as a concrete pour that cannot stop.': '15 جون سے 15 ستمبر تک، {from} سے {to} تک دھوپ میں باہر کام کی اجازت نہیں ہے۔ صرف اندر یا سائے والے کام، یا چھوٹ والے کام کے لیے پنچ اِن کریں، جیسے کنکریٹ کی ڈھلائی جو روکی نہیں جا سکتی۔',
  'Indoor or exempt work': 'اندر کا یا چھوٹ والا کام',
  'That TRN doesn\'t look right. It has 15 digits, like 100123456700003.': 'یہ TRN درست نہیں لگ رہا۔ اس میں 15 ہندسے ہوتے ہیں، جیسے 100123456700003۔',
  'Write from the email address on your account. We reply within 30 days. If you are not satisfied, you can complain to the UAE data protection authority.': 'اپنے اکاؤنٹ والے ای میل ایڈریس سے لکھیں۔ ہم 30 دن کے اندر جواب دیتے ہیں۔ اگر آپ مطمئن نہیں ہیں تو UAE (متحدہ عرب امارات) کی ڈیٹا پروٹیکشن اتھارٹی کو شکایت کر سکتے ہیں۔',
  'Data sent outside the UAE': 'UAE سے باہر بھیجا گیا ڈیٹا',
  'Our cloud is in India, and the services above are in India and the USA. Each gets only what it needs, under a contract that requires it to protect the data.': 'ہمارا کلاؤڈ انڈیا میں ہے، اور اوپر بتائی گئی سروسز انڈیا اور امریکہ میں ہیں۔ ہر ایک کو صرف وہی ملتا ہے جو اسے چاہیے، ایک معاہدے کے تحت جس میں ڈیٹا کی حفاظت لازمی ہے۔',
  'Your rights under the PDPL': 'PDPL کے تحت آپ کے حقوق',
  'Ask us for a copy of your data, to correct or erase it, to stop using it, or to send it to another organisation. Write to info@mldynamic.com. We reply within 30 days.': 'اپنے ڈیٹا کی کاپی لینے، اسے درست کروانے یا مٹوانے، اس کا استعمال بند کروانے، یا اسے کسی دوسرے ادارے کو بھیجنے کے لیے ہم سے کہیں۔ info@mldynamic.com پر لکھیں۔ ہم 30 دن کے اندر جواب دیتے ہیں۔',
  'Write to info@mldynamic.com with "Privacy" in the subject. If you are not satisfied, you can complain to the UAE data protection authority.': 'info@mldynamic.com پر لکھیں اور موضوع میں "Privacy" لکھیں۔ اگر آپ مطمئن نہیں ہیں تو UAE کی ڈیٹا پروٹیکشن اتھارٹی کو شکایت کر سکتے ہیں۔',
  'CIS work for a VAT-registered contractor who is not the end user. The VAT is shown, and the customer pays it to HMRC.': 'ایسے VAT رجسٹرڈ ٹھیکیدار کے لیے CIS کام جو آخری صارف نہیں۔ VAT دکھایا جاتا ہے، اور گاہک اسے HMRC کو ادا کرتا ہے۔',
  'Domestic reverse charge': 'ملکی ریورس چارج',
  'Materials or plant hire': 'سامان یا مشینری کرایہ',
  'No CIS is taken off this line': 'اس لائن سے CIS نہیں کٹتا',
  '{tax} (reverse charge, not added)': '{tax} (ریورس چارج، شامل نہیں)',
  'below the minimum wage of {amount}/hr': 'کم از کم اجرت {amount}/گھنٹہ سے کم',
  'Your location and a selfie when you check in or out, and your location when you punch a worker in, set a site location or take a site photo, to show the work was done at the site. The app asks you first. Never in the background. FieldOS does not use face recognition.': 'حاضری لگاتے یا چھٹی درج کرتے وقت آپ کی لوکیشن اور ایک سیلفی، اور کسی مزدور کا پنچ لگانے، سائٹ کی لوکیشن طے کرنے یا سائٹ کی تصویر لینے پر آپ کی لوکیشن، یہ دکھانے کے لیے کہ کام سائٹ پر ہوا۔ ایپ پہلے آپ سے پوچھتی ہے۔ کبھی پس منظر میں نہیں۔ FieldOS چہرے کی شناخت استعمال نہیں کرتا۔',
  'Write from the email address on your account. We reply within one month. If you are not satisfied, you can complain to the Information Commissioner\'s Office.': 'اپنے اکاؤنٹ والے ای میل پتے سے لکھیں۔ ہم ایک مہینے کے اندر جواب دیتے ہیں۔ اگر آپ مطمئن نہیں ہیں تو Information Commissioner\'s Office میں شکایت کر سکتے ہیں۔',
  'Gross payment status (0%)': 'گراس پیمنٹ اسٹیٹس (0%)',
  'Registered (20%)': 'رجسٹرڈ (20%)',
  'Not registered (30%)': 'غیر رجسٹرڈ (30%)',
  'Add the people on a monthly salary. Each month FieldOS works out their pay for the days worked, EPF, SOCSO, EIS and advance recovery, and makes the payslips.': 'ماہانہ تنخواہ والے لوگ شامل کریں۔ ہر مہینے FieldOS کام کے دنوں کی تنخواہ، EPF، SOCSO، EIS اور ایڈوانس کی وصولی نکال کر پے سلپ بناتا ہے۔',
  'EPF to pay': 'جمع کرنا ہے: EPF',
  'SOCSO to pay': 'جمع کرنا ہے: SOCSO',
  'EIS to pay': 'جمع کرنا ہے: EIS',
  'EPF': 'EPF',
  'SOCSO': 'SOCSO',
  'EIS': 'EIS',
  'Employer pays on top': 'کمپنی اوپر سے دیتی ہے',
  'Housing allowance (₹)': 'مکان الاؤنس (₹)',
  'EPF (KWSP)': 'EPF (KWSP)',
  'SOCSO and EIS': 'SOCSO اور EIS',
  'On pay up to ₹6,000 a month': '₹6,000 ماہانہ تک کی تنخواہ پر',
  'EPF, SOCSO and EIS: workers {ee} · employer {er}': 'EPF، SOCSO اور EIS: مزدور {ee} · کمپنی {er}',
  'EPF, SOCSO and EIS are worked out on the wages in this sheet. They are due on a month\'s wages, so check them against the month\'s total before paying them over. A worker with a PLKS permit on file is counted as foreign: EPF 2% each, SOCSO as for a local worker, no EIS.': 'EPF، SOCSO اور EIS اس شیٹ کی اجرت پر نکالے گئے ہیں۔ یہ مہینے کی اجرت پر واجب ہوتے ہیں، اس لیے جمع کرنے سے پہلے مہینے کے کل سے ملا لیں۔ جس مزدور کا PLKS پرمٹ درج ہے اسے غیر ملکی مانا جاتا ہے: EPF دونوں طرف 2%، SOCSO مقامی مزدور کی طرح، EIS نہیں۔',
  'Cut from pay: {items}': 'تنخواہ سے کٹا: {items}',
  'Employer pays: {items}': 'کمپنی دیتی ہے: {items}',
  'Net pay {amount}': 'ہاتھ میں تنخواہ {amount}',
  // Forgot PIN: signing in to the cloud account again.
  'Forgot PIN?': 'PIN بھول گئے؟',
  'Confirm it is you': 'تصدیق کریں کہ یہ آپ ہیں',
  'To choose a new PIN, sign in again to {email}.': 'نیا PIN چننے کے لیے {email} میں دوبارہ سائن ان کریں۔',
  'Use my password': 'میرا پاس ورڈ استعمال کریں',
  'Email me a code': 'مجھے کوڈ ای میل کریں',
  'We emailed a sign-in code to {email}.': 'ہم نے {email} پر سائن ان کوڈ ای میل کیا ہے۔',
  'That password is not right.': 'یہ پاس ورڈ درست نہیں ہے۔',
  'That code is wrong or has expired.': 'یہ کوڈ غلط ہے یا اس کی میعاد ختم ہو گئی ہے۔',
  'That is a different account. Use {email}.': 'یہ کوئی دوسرا اکاؤنٹ ہے۔ {email} استعمال کریں۔',
  'That did not go through. Check the internet and try again.': 'یہ نہیں ہو سکا۔ انٹرنیٹ چیک کریں اور دوبارہ کوشش کریں۔',
  'This phone is not signed in to the cloud': 'یہ فون کلاؤڈ میں سائن ان نہیں ہے',
  'The data on this phone goes with the cloud account {email}. Sign in to it to keep the data and choose a new PIN.': 'اس فون کا ڈیٹا کلاؤڈ اکاؤنٹ {email} کا ہے۔ ڈیٹا رکھنے اور نیا PIN چننے کے لیے اس میں سائن ان کریں۔',
  'The data on this phone was never linked to a cloud account, so signing in cannot show that it is yours. Without the PIN, the only way in is to erase this phone and start over.': 'اس فون کا ڈیٹا کبھی کسی کلاؤڈ اکاؤنٹ سے نہیں جڑا، اس لیے سائن ان کرنے سے یہ ثابت نہیں ہوتا کہ یہ آپ کا ہے۔ PIN کے بغیر اندر جانے کا واحد راستہ یہ ہے کہ اس فون کو مٹا کر دوبارہ شروع کریں۔',
  'Sign in to keep my data': 'سائن ان کریں اور میرا ڈیٹا رکھیں',
  'Erase this phone and start over': 'اس فون کو مٹائیں اور دوبارہ شروع کریں',
  'Erase this phone?': 'اس فون کو مٹائیں؟',
  'Everything on this phone that is not backed up to the cloud is lost for good: sites, workers, attendance, bills, photos and the rest. This cannot be undone.': 'اس فون پر جو کچھ کلاؤڈ میں بیک اپ نہیں ہے وہ ہمیشہ کے لیے ختم ہو جائے گا: سائٹس، مزدور، حاضری، بل، تصویریں اور باقی سب۔ اسے واپس نہیں لایا جا سکتا۔',
  'To confirm, type {word} below.': 'تصدیق کے لیے نیچے {word} لکھیں۔',
  'You can also type {word}.': 'آپ {word} بھی لکھ سکتے ہیں۔',
  'Confirmation word': 'تصدیقی لفظ',
  'Erase everything': 'سب کچھ مٹائیں',
  'ERASE': 'مٹائیں',
  'The phone could not be erased. Close FieldOS, open it again and try once more.': 'فون مٹایا نہیں جا سکا۔ FieldOS بند کریں، دوبارہ کھولیں اور ایک بار اور کوشش کریں۔',
  '{amount}/hr': '{amount}/گھنٹہ',
  '{amount} an hour': '{amount} فی گھنٹہ',
  'OT {h} h, {amount}': 'اوور ٹائم {h} گھنٹے، {amount}',
  'Hi! I am Mitra, your site buddy': 'السلام علیکم! میں Mitra ہوں، آپ کا سائٹ ساتھی',
  'Let me show you one day on a sample site, a two-storey house. It takes two minutes and does not touch your own data.': 'آئیں آپ کو ایک نمونہ سائٹ کا ایک دن دکھاؤں: دو منزلہ گھر۔ اس میں دو منٹ لگتے ہیں اور آپ کے اپنے ڈیٹا کو نہیں چھیڑتا۔',
  'Not sure where something is? Tap Ask FieldOS at the top and type or speak, like "add 500 for cement". It does the work and asks you to tap Save first.': 'پتا نہیں کوئی چیز کہاں ہے؟ اوپر FieldOS سے پوچھیں پر ٹیپ کریں اور لکھیں یا بولیں، جیسے "سیمنٹ کے لیے 500 شامل کرو"۔ یہ کام کر دیتا ہے اور پہلے آپ سے "محفوظ کریں" پر ٹیپ کرواتا ہے۔',
  'Check workers in as they arrive, or mark the whole crew at once. Hours and overtime are worked out for you.': 'ورکرز کے آتے ہی ان کی حاضری لگائیں، یا پوری ٹولی ایک ساتھ لگائیں۔ گھنٹے اور اوور ٹائم آپ کے لیے نکال دیے جاتے ہیں۔',
  'Every cost on site': 'سائٹ کا ہر خرچ',
  'Money received, money spent and the balance, by category. Client bills and tax invoices are made here too.': 'زمرے کے حساب سے موصول رقم، خرچ اور بیلنس۔ کلائنٹ کے بل اور ٹیکس انوائسز بھی یہیں بنتی ہیں۔',
  'Tap Speak report and just talk, in your language or in English. FieldOS writes the report, adds the day\'s numbers and shares it as a PDF.': 'رپورٹ بولیں پر ٹیپ کریں اور بس بولیں، اپنی زبان میں یا انگریزی میں۔ FieldOS رپورٹ لکھتا ہے، دن کے اعداد شامل کرتا ہے اور اسے PDF کے طور پر شیئر کرتا ہے۔',
  'The wage sheet adds up each worker\'s pay, advances and what is still due, ready to pay or send to the office.': 'تنخواہ شیٹ ہر ورکر کی اجرت، ایڈوانس اور باقی رقم جوڑ دیتی ہے، ادائیگی یا دفتر بھیجنے کے لیے تیار۔',
  'Spending is {amount} over the BOQ budget.': 'خرچ BOQ بجٹ سے {amount} زیادہ ہے۔',
  'Over budget on {item}: spent {spent} of {budget}.': '{item} پر بجٹ سے زیادہ: {budget} میں سے {spent} خرچ۔',
  'Close to budget on {item}: {spent} of {budget} ({pct}%).': '{item} پر بجٹ کے قریب: {budget} میں سے {spent} ({pct}%)۔',
  '{amount} spent without a BOQ item.': 'BOQ آئٹم کے بغیر {amount} خرچ۔',
  'Purchase request': 'خریداری کی درخواست',
  'Tasks show how far each job has got and what is slipping. The ground beam is late, so it is marked in red before anyone has to ask.': 'کام دکھاتے ہیں کہ ہر کام کتنا ہوا اور کیا پیچھے رہ رہا ہے۔ گراؤنڈ بیم لیٹ ہے، اس لیے کسی کے پوچھنے سے پہلے ہی سرخ نشان لگ جاتا ہے۔',
};
